async function searchProducts(q: string) {
  const db = await pool.connect();
  // BUG: user input concatenated straight into SQL
  const sql =
    "SELECT id, name, price FROM products WHERE name LIKE '%" + q + "%'";
  const { rows } = await db.query(sql);
  return rows;
}

remediation.patch:
async function searchProducts(q: string) {
  const db = await pool.connect();
  const sql = 'SELECT id, name, price FROM products WHERE name ILIKE $1';
  const { rows } = await db.query(sql, ['%' + q + '%']);
  return rows;
}

