router.get('/api/invoices/:id', requireAuth, async (req, res) => {
  // BUG: fetches by id but never checks it belongs to req.user
  const inv = await db.query('SELECT * FROM invoices WHERE id = $1', [req.params.id]);
  res.json(inv.rows[0]);
});

remediation.patch:
const inv = await db.query(
  'SELECT * FROM invoices WHERE id = $1 AND user_id = $2',
  [req.params.id, req.user.id]
);
if (!inv.rows[0]) return res.status(404).end();

